package de.fitnesscoach.ui;
import android.content.Intent;import android.os.Bundle;import android.view.View;import androidx.activity.result.ActivityResultLauncher;import androidx.appcompat.app.AppCompatActivity;import androidx.health.connect.client.HealthConnectClient;import androidx.health.connect.client.contracts.HealthPermissionsRequestContract;import androidx.lifecycle.ViewModelProvider;import androidx.recyclerview.widget.LinearLayoutManager;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import de.fitnesscoach.R;import de.fitnesscoach.data.db.FitnessCoachDatabase;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.GoalOnboardingMigrator;import de.fitnesscoach.databinding.ActivityMainBinding;import de.fitnesscoach.health.*;import de.fitnesscoach.ui.today.*;import de.fitnesscoach.ui.plan.PlanViewModel;import de.fitnesscoach.ui.plan.PlanDiagnosticsViewModel;import de.fitnesscoach.ui.coach.*;
public class MainActivity extends AppCompatActivity{private ActivityMainBinding binding;private HealthPermissionManager healthPermissionManager;private ActivityResultLauncher<Set<? extends String>>launcher;private TodayDiagnosticsViewModel today;private TodayOverviewViewModel overview;private FitnessDiagnosticsViewModel fitness;private PlanViewModel plan;private PlanDiagnosticsViewModel planDiagnostics;private CoachViewModel coach;private CoachChatAdapter coachAdapter;private Long reviewWorkoutId;private final ExecutorService ex=Executors.newSingleThreadExecutor();private final AtomicBoolean syncing=new AtomicBoolean(false);@Override protected void onCreate(Bundle s){super.onCreate(s);binding=ActivityMainBinding.inflate(getLayoutInflater());setContentView(binding.getRoot());healthPermissionManager=new HealthPermissionManager(this);today=new ViewModelProvider(this).get(TodayDiagnosticsViewModel.class);overview=new ViewModelProvider(this).get(TodayOverviewViewModel.class);fitness=new ViewModelProvider(this).get(FitnessDiagnosticsViewModel.class);plan=new ViewModelProvider(this).get(PlanViewModel.class);planDiagnostics=new ViewModelProvider(this).get(PlanDiagnosticsViewModel.class);coach=new ViewModelProvider(this).get(CoachViewModel.class);coachAdapter=new CoachChatAdapter();binding.coachMessages.setLayoutManager(new LinearLayoutManager(this));binding.coachMessages.setAdapter(coachAdapter);today.getState().observe(this,x->{renderToday(x);fitness.selectDate(x.date);overview.setDate(x.date);});overview.getState().observe(this,x->{if(x!=null){binding.todayOverview.setText(x.summary);reviewWorkoutId=x.reviewableWorkoutId;binding.reviewCompletedWorkout.setVisibility(reviewWorkoutId==null?View.GONE:View.VISIBLE);}});fitness.getState().observe(this,x->{if(x!=null)binding.fitnessIntelligenceDiagnostics.setText(x.text);});plan.getState().observe(this,w->{renderPlan(w);planDiagnostics.setWeek(plan.getWeek());});planDiagnostics.getState().observe(this,x->{if(x!=null)binding.planDiagnostics.setText(x.text);});coach.getState().observe(this,this::renderCoach);binding.planPrevious.setOnClickListener(v->plan.previous());binding.planNext.setOnClickListener(v->plan.next());binding.adaptTodayPlan.setOnClickListener(v->{plan.adaptToday();planDiagnostics.refresh();overview.refresh();});binding.refreshPlanDiagnostics.setOnClickListener(v->planDiagnostics.setWeek(plan.getWeek()));binding.todayPreviousDay.setOnClickListener(v->today.previousDay());binding.todayNextDay.setOnClickListener(v->today.nextDay());binding.recalculateFitnessIntelligence.setOnClickListener(v->{fitness.recalculate();overview.refresh();});binding.dailyCheckIn.setOnClickListener(v->startActivity(new Intent(this,CheckInActivity.class)));binding.openCoachFromToday.setOnClickListener(v->binding.bottomNavigation.setSelectedItemId(R.id.nav_coach));binding.reviewCompletedWorkout.setOnClickListener(v->{if(reviewWorkoutId!=null)startActivity(new Intent(this,WorkoutReviewActivity.class).putExtra(WorkoutReviewActivity.EXTRA_WORKOUT_ID,reviewWorkoutId));});binding.coachSend.setOnClickListener(v->sendCoachInput());binding.coachRetry.setOnClickListener(v->coach.retry());binding.coachQuickToday.setOnClickListener(v->coach.send(getString(R.string.coach_quick_today)));binding.coachQuickWeek.setOnClickListener(v->coach.send(getString(R.string.coach_quick_week)));binding.coachQuickChange.setOnClickListener(v->coach.send(getString(R.string.coach_quick_change)));binding.coachQuickProgress.setOnClickListener(v->coach.send(getString(R.string.coach_quick_progress)));binding.updateHealthData.setOnClickListener(v->sync(true));binding.editFitnessProfile.setOnClickListener(v->startActivity(new Intent(this,ProfileActivity.class)));binding.managePrimaryGoal.setOnClickListener(v->startActivity(new Intent(this,GoalActivity.class)));ex.execute(()->GoalOnboardingMigrator.migrateIfNeeded(this));launcher=registerForActivityResult(new HealthPermissionsRequestContract(HealthConnectClient.DEFAULT_PROVIDER_PACKAGE_NAME),g->{refreshPermissions();HealthSyncScheduler.reconcile(this);sync(true);});binding.requestHealthPermissions.setOnClickListener(v->{Set<String>m=healthPermissionManager.getMissingRequiredPermissions();if(!m.isEmpty())launcher.launch(m);});binding.requestOptionalHealthPermissions.setOnClickListener(v->{Set<String>m=healthPermissionManager.getMissingOptionalPermissions();if(!m.isEmpty())launcher.launch(m);});binding.bottomNavigation.setOnItemSelectedListener(i->{show(i.getItemId());return true;});if(s==null)binding.bottomNavigation.setSelectedItemId(R.id.nav_today);HealthSyncScheduler.reconcile(this);sync(false);today.refresh();}
private void sendCoachInput(){String text=binding.coachInput.getText().toString();if(text.trim().isEmpty())return;binding.coachInput.setText("");coach.send(text);}
private void renderCoach(CoachUiState x){if(x==null)return;coachAdapter.submit(x.messages);if(!x.messages.isEmpty())binding.coachMessages.scrollToPosition(x.messages.size()-1);binding.coachLoading.setVisibility(x.loading?View.VISIBLE:View.GONE);binding.coachError.setVisibility(x.error==null?View.GONE:View.VISIBLE);binding.coachError.setText(x.error==null?"":x.error);binding.coachRetry.setVisibility(x.error!=null&&!x.validationError?View.VISIBLE:View.GONE);binding.coachSend.setEnabled(!x.loading);binding.coachQuickToday.setEnabled(!x.loading);binding.coachQuickWeek.setEnabled(!x.loading);binding.coachQuickChange.setEnabled(!x.loading);binding.coachQuickProgress.setEnabled(!x.loading);binding.coachContextDebug.setText(x.debugContext);if(!x.loading&&x.error==null){overview.refresh();plan.load();planDiagnostics.refresh();}}
private void show(int id){binding.todayDiagnosticsPanel.setVisibility(id==R.id.nav_today?View.VISIBLE:View.GONE);binding.planPanel.setVisibility(id==R.id.nav_plan?View.VISIBLE:View.GONE);binding.coachPanel.setVisibility(id==R.id.nav_coach?View.VISIBLE:View.GONE);binding.healthPermissionsPanel.setVisibility(id==R.id.nav_profile?View.VISIBLE:View.GONE);if(id==R.id.nav_today){set(R.string.nav_today,R.string.placeholder_today);today.refresh();fitness.refresh();overview.refresh();}else if(id==R.id.nav_plan){set(R.string.nav_plan,R.string.placeholder_plan);plan.load();planDiagnostics.setWeek(plan.getWeek());}else if(id==R.id.nav_progress)set(R.string.nav_progress,R.string.placeholder_progress);else if(id==R.id.nav_coach)set(R.string.nav_coach,R.string.placeholder_coach);else{set(R.string.nav_profile,R.string.placeholder_profile);refreshPermissions();refreshSync();}}
private void renderPlan(List<PlannedWorkoutEntity>w){binding.planWeek.setText(plan.getWeek()+" – "+plan.getWeek().plusDays(6));StringBuilder b=new StringBuilder();if(w==null||w.isEmpty())b.append("Keine verfügbaren Trainingstage. Prüfe die Verfügbarkeit im Profil.");else for(PlannedWorkoutEntity p:w)b.append(GermanLabels.day(p.date.getDayOfWeek())).append(" ").append(p.date).append("\n  ").append(GermanLabels.workout(p.workoutType)).append(" · ").append(p.plannedDurationMinutes==null?"nicht verfügbar":p.plannedDurationMinutes+" Min.").append(" · ").append(GermanLabels.workoutStatus(p.status)).append(" · v").append(p.version).append("\n  ").append(p.description==null?"Keine Details":p.description).append("\n\n");binding.planWorkouts.setText(b.toString().trim());}
private void renderToday(TodayDiagnosticsUiState x){if(x==null)return;binding.todaySelectedDate.setText(x.date.toString());binding.todayNextDay.setEnabled(x.date.isBefore(LocalDate.now()));binding.todayHealthConnectStatus.setText(x.healthConnectAvailable?"Health Connect: verfügbar":"Health Connect: nicht verfügbar");binding.todaySyncDiagnostics.setText("Letzter Versuch: "+fmt(x.lastAttemptAt)+"\nLetzter Erfolg: "+fmt(x.lastSuccessfulSyncAt)+(x.lastSyncError==null?"":"\nLetzter Fehler: "+x.lastSyncError));StringBuilder b=new StringBuilder();for(TodayDiagnosticsUiState.MetricRow r:x.metrics)b.append(r.label).append(": ").append(r.value).append(" | ").append(r.quality).append("\n");binding.todayHealthMetrics.setText(b.toString());binding.todayEmptyState.setVisibility(x.hasDailyData?View.GONE:View.VISIBLE);binding.todayEmptyState.setText(x.emptyMessage==null?"":x.emptyMessage);}
private void refreshPermissions(){if(binding==null)return;HealthPermissionSnapshot s=healthPermissionManager.getSnapshot();binding.updateHealthData.setEnabled(s.hasAnyRequiredGrant()&&!syncing.get());binding.requestHealthPermissions.setEnabled(s.isHealthConnectAvailable()&&!s.allRequiredGranted());binding.requestOptionalHealthPermissions.setEnabled(s.isHealthConnectAvailable()&&!healthPermissionManager.getMissingOptionalPermissions().isEmpty());StringBuilder b=new StringBuilder("Health Connect\n");for(HealthPermissionSpec p:HealthPermissionSpec.values())b.append(permissionState(s.getState(p))).append(" ").append(p.getDisplayName()).append(p.isOptional()?" (optional)":"").append('\n');binding.healthPermissionsStatus.setText(b.toString());}private String permissionState(HealthPermissionSnapshot.State s){switch(s){case GRANTED:return"Erlaubt";case DENIED:return"Nicht erlaubt";default:return"Unbekannt";}}
private void sync(boolean force){HealthPermissionSnapshot snap=healthPermissionManager.getSnapshot();if(!snap.hasAnyRequiredGrant()||!syncing.compareAndSet(false,true))return;ex.execute(()->{try{HealthSyncStateEntity st=FitnessCoachDatabase.getInstance(this).healthSyncDao().getState();if(!force&&!HealthSyncPolicy.shouldSyncOnAppStart(st==null?null:st.lastSuccessfulSyncAt,Instant.now()))return;new HealthSyncCoordinator(this).runSync();runOnUiThread(()->{today.refresh();fitness.recalculate();overview.refresh();if(planDiagnostics!=null)planDiagnostics.refresh();});}finally{syncing.set(false);runOnUiThread(this::refreshPermissions);}});}private void refreshSync(){ex.execute(()->{HealthSyncStateEntity s=FitnessCoachDatabase.getInstance(this).healthSyncDao().getState();runOnUiThread(()->binding.healthSyncStatus.setText(s==null||s.lastSuccessfulSyncAt==null?"Noch nie synchronisiert":"Letzte Synchronisierung: "+fmt(s.lastSuccessfulSyncAt)));});}@Override protected void onResume(){super.onResume();refreshPermissions();refreshSync();if(today!=null)today.refresh();if(fitness!=null)fitness.refresh();if(overview!=null)overview.refresh();if(planDiagnostics!=null)planDiagnostics.refresh();}@Override protected void onDestroy(){super.onDestroy();ex.shutdownNow();}private String fmt(Instant i){return i==null?"noch nie":DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(ZoneId.systemDefault()).format(i);}private void set(int a,int b){binding.screenTitle.setText(a);binding.screenBody.setText(b);}}
